import pandas as pd
import ast

def processing(dfs):
    df = dfs[0].copy()

    # 1. Filter by created_at in June 2025
    df['created_at'] = pd.to_datetime(df['created_at'])
    june_shipments = df[(df['created_at'] >= '2025-06-01') & (df['created_at'] < '2025-07-01')].copy()

    # 2. Function to check for 'DELIVERED'
    def is_delivered(tracking_str):
        if not isinstance(tracking_str, str):
            return False
        try:
            # Use ast.literal_eval for Python dictionary syntax string
            data = ast.literal_eval(tracking_str)
            events = data.get('events', [])
            return any(isinstance(event, dict) and event.get('code') == 'DELIVERED' for event in events)
        except (ValueError, SyntaxError, AttributeError):
            return False

    # 3. Apply the function
    june_shipments['is_delivered'] = june_shipments['tracking'].apply(is_delivered)

    # Count
    result_count = june_shipments['is_delivered'].sum()

    return pd.DataFrame({'delivered_shipment_count': [int(result_count)]})
